changes.before:
title:'Matilda: estates and allegiances', intro:'Review the household, local obligations and relations with the imperial and papal courts. Choose what your actual jurisdiction and resources can sustain.',
stages:[
  { id:'matilda_household', name:'The Canossan household', year:1096, season:0,
    text:'Your household is already separated from Welf. Consider your present responsibilities without assuming a new marriage, reconciliation or legal annulment.',
    choices:[
      { id:'matilda_review_household', label:'Prioritize the household', detail:'Record a household priority. No relative, spouse, payment or marriage decision is created.', operation:'agenda_priority' },
      { id:'matilda_keep_household', label:'Keep the present arrangements', detail:'Continue with the existing household and ordinary family decisions.', operation:'agenda_priority' }
    ] },
  { id:'matilda_boundaries', name:'Boundaries and obligations', year:1096, season:0,
    text:'Estate rights, church property and urban government overlap. Review the counties and obligations you actually hold before choosing a policy.',
    choices:[
      { id:'matilda_review_rights', label:'Prioritize existing rights', detail:'Record a review priority. Actual grants, dues and disputes require their own ordinary decisions.', operation:'agenda_priority' },
      { id:'matilda_keep_obligations', label:'Retain existing obligations', detail:'Record continuity without transferring property or imposing a new payment.', operation:'agenda_priority' }
    ] },
  { id:'matilda_separated_alliance', name:'An alliance after separation', year:1096, season:0,
    text:'The former Welf alliance does not settle your current diplomatic options. Review the living courts and their actual relations before making a commitment.',
    choices:[
      { id:'matilda_review_alliances', label:'Prioritize available alliances', detail:'Record a diplomatic priority. No Welf encounter, reconciliation, pact or dowry transaction follows.', operation:'agenda_priority' },
      { id:'matilda_keep_alliances', label:'Retain current relations', detail:'Keep the current diplomatic arrangements without creating an obligation.', operation:'agenda_priority' }
    ] },
  { id:'matilda_imperial_pressure', name:'Imperial pressure', year:1096, season:1,
    text:'Imperial claims form part of the opening conflict, but a threat is not an army at your gates. Review actual wars and neighboring forces before choosing defense or negotiation.',
    choices:[
      { id:'matilda_prioritize_defense', label:'Prioritize local defense', detail:'Record a defensive priority. Ordinary army controls still require lawful authority, available forces and actual funds.', operation:'agenda_priority' },
      { id:'matilda_consider_negotiation', label:'Prioritize negotiation', detail:'Record a preference for ordinary diplomacy, subject to living parties and their consent.', operation:'agenda_priority' },
      { id:'matilda_keep_frontier', label:'Keep current dispositions', detail:'Create no war, army, treaty or automatic imperial withdrawal.', operation:'agenda_priority' }
    ] },
  { id:'matilda_papal_relationship', name:'The papal relationship', year:1096, season:1,
    text:'Consider cooperation with the current papal court alongside local responsibilities. A changed pope or lost access may call for a different policy; no letter or audience is presumed.',
    choices:[
      { id:'matilda_prioritize_cooperation', label:'Prioritize supported cooperation', detail:'Record this policy without granting church property, making a contribution or obtaining protection.', operation:'agenda_priority' },
      { id:'matilda_prioritize_local_duties', label:'Prioritize local obligations', detail:'Keep attention on the responsibilities you actually hold, without changing relations with the pope.', operation:'agenda_priority' }
    ] },
  { id:'matilda_sustainable_commitments', name:'What can be sustained', year:1096, season:2,
    text:'Review the actual treasury and obligations before taking on a new commitment. A defense plan cannot pay troops or supply a campaign by itself.',
    choices:[
      { id:'matilda_review_affordable_defense', label:'Prioritize affordable defense', detail:'Record intent only. Recruiting, paying and supplying troops retain their ordinary costs and gates.', operation:'agenda_priority' },
      { id:'matilda_retain_commitments', label:'Retain existing commitments', detail:'Record a preference without spending private or public funds.', operation:'agenda_priority' }
    ] },
  { id:'matilda_changing_jurisdiction', name:'A changing jurisdiction', year:1096, season:2,
    text:'Review the counties that remain under your authority. Present possession does not settle every estate claim, and this review promises no recovery of a lost city.',
    choices:[
      { id:'matilda_review_jurisdiction', label:'Prioritize current local arrangements', detail:'Record a priority for the jurisdiction you retain. No county is transferred or restored.', operation:'agenda_priority' },
      { id:'matilda_keep_jurisdiction', label:'Retain current arrangements', detail:'Continue without changing holders, rights or legal claims.', operation:'agenda_priority' }
    ] },
  { id:'matilda_continuation', name:'Continue governing', year:1096, season:3,
    text:'Conclude this opening review from your actual position. Ordinary government continues, and any live war or family obligation keeps its own terms.',
    choices:[
      { id:'matilda_finish_review', label:'Conclude the opening review', detail:'Finish this personal program without a reward, inheritance, marriage ruling or forced peace.', operation:'agenda_finish' },
      { id:'matilda_continue_governing', label:'Retain a governing priority', detail:'Complete the program with ordinary decisions still available and no new commitment.', operation:'agenda_priority' }
    ] }

changes.after:
title:'Matilda: estates and allegiances', intro:'You hold Tuscany from Modena to Pisa and Siena. Emperor Henry IV is still in Italy with his army, and Pope Urban II is in France calling knights to Jerusalem. These priorities shape your court’s story; orders, payments and wars go through Rank & Realm, Land and the map.',
stages:[
  { id:'matilda_household', name:'The Canossan household', year:1096, season:0,
    text:'Welf V left you in 1095, and his family is making its peace with Emperor Henry IV.',
    choices:[
      { id:'matilda_review_household', label:'Put your household at Canossa first', detail:'Your attention turns to your household at Canossa.', operation:'agenda_priority' },
      { id:'matilda_keep_household', label:'Let the break with Welf stand', detail:'You leave the separation as it is and turn to governing.', operation:'agenda_priority' }
    ] },
  { id:'matilda_boundaries', name:'Boundaries and obligations', year:1096, season:0,
    text:'In Modena, Lucca, Pisa, Firenze and Siena your estates overlap with church lands and the rights of the towns.',
    choices:[
      { id:'matilda_review_rights', label:'Defend your rights in the Tuscan towns', detail:'You turn to the dues and services the towns and bishops owe you.', operation:'agenda_priority' },
      { id:'matilda_keep_obligations', label:'Honor your gifts to the churches', detail:'You turn to keeping the grants and promises you have made to the Tuscan churches.', operation:'agenda_priority' }
    ] },
  { id:'matilda_separated_alliance', name:'An alliance after separation', year:1096, season:0,
    text:'Without Welf, your allies against Henry IV are his rebel son Conrad and the Lombard towns of Milan, Cremona, Lodi and Piacenza.',
    choices:[
      { id:'matilda_review_alliances', label:'Seek new allies against Henry IV', detail:'You turn to the courts that might stand with you against the emperor.', operation:'agenda_priority' },
      { id:'matilda_keep_alliances', label:'Keep faith with Conrad and the Lombard towns', detail:'You stay with the allies you already have.', operation:'agenda_priority' }
    ] },
  { id:'matilda_imperial_pressure', name:'Imperial pressure', year:1096, season:1,
    text:'Henry IV still keeps his army around Verona and has not given up his war on you.',
    choices:[
      { id:'matilda_prioritize_defense', label:'Hold the castles of the Apennines', detail:'You turn to the castles and garrisons that guard Canossa.', operation:'agenda_priority' },
      { id:'matilda_consider_negotiation', label:'Open talks with Henry IV', detail:'You turn to seeking terms with the emperor, if he will listen.', operation:'agenda_priority' },
      { id:'matilda_keep_frontier', label:'Keep your forces where they stand', detail:'You leave your garrisons as they are and watch the emperor.', operation:'agenda_priority' }
    ] },
  { id:'matilda_papal_relationship', name:'The papal relationship', year:1096, season:1,
    text:'Pope Urban II is coming back to Italy from France and counts on you as his firmest ally against Henry IV.',
    choices:[
      { id:'matilda_prioritize_cooperation', label:'Stand with Pope Urban II', detail:'You turn to the pope’s cause and his reform of the church in Italy.', operation:'agenda_priority' },
      { id:'matilda_prioritize_local_duties', label:'Put Tuscany ahead of Rome', detail:'You turn to your own lands before the pope’s affairs.', operation:'agenda_priority' }
    ] },
  { id:'matilda_sustainable_commitments', name:'What can be sustained', year:1096, season:2,
    text:'Years of war with Henry IV have drained your treasury, and soldiers, castles and gifts to the church all draw on it.',
    choices:[
      { id:'matilda_review_affordable_defense', label:'Pay only for the defense you can afford', detail:'You turn to keeping only the garrisons your treasury can pay.', operation:'agenda_priority' },
      { id:'matilda_retain_commitments', label:'Keep your promises and gifts as they are', detail:'You turn to the payments and gifts you have already promised.', operation:'agenda_priority' }
    ] },
  { id:'matilda_changing_jurisdiction', name:'A changing jurisdiction', year:1096, season:2,
    text:'Pisa, Lucca and the other towns are taking more of their own government, and not every old Canossan claim still holds.',
    choices:[
      { id:'matilda_review_jurisdiction', label:'Work with the towns you still rule', detail:'You turn to the counties and towns that still answer to you.', operation:'agenda_priority' },
      { id:'matilda_keep_jurisdiction', label:'Leave the towns and bishops their rights', detail:'You turn to other business and leave the towns’ rights as they are.', operation:'agenda_priority' }
    ] },
  { id:'matilda_continuation', name:'Continue governing', year:1096, season:3,
    text:'Winter 1096: Henry IV is still in Italy, and the armies bound for Jerusalem have marched east. Close your opening program here.',
    choices:[
      { id:'matilda_finish_review', label:'Conclude the opening review', detail:'Your opening program ends here; your wars and alliances go on as they stand.', operation:'agenda_finish' },
      { id:'matilda_continue_governing', label:'Keep governing Tuscany as before', detail:'You close the review with your attention on governing Tuscany.', operation:'agenda_priority' }
    ] }

changes.before:
intro:'Choose priorities for the court and the territory you actually hold. Ordinary decisions determine the costs and results.',
stages:[
  { id:'city', name:'A city already held', year:1096, season:0,
    text:'Valencia has been in your hands since 1094. The county on the map approximates the city’s lordship, including Murviedro, which was still outside your historical control. Decide what needs attention first.',
    choices:[
      { id:'city_administration', label:'Put local administration first', detail:'Record a priority. Review actual government decisions through the ordinary controls.', operation:'agenda_priority' },
      { id:'city_defense', label:'Put defense preparation first', detail:'Record an intention. Raising forces still requires lawful authority, real funds and ordinary army controls.', operation:'agenda_priority' },
      { id:'city_retain', label:'Keep present priorities', detail:'Continue with the current government and resources.', operation:'agenda_priority' }
    ] },
  { id:'household', name:'The existing household', year:1096, season:0,
    text:'Jimena, Diego, Cristina and Maria form your named household. Their working ages and opening residence in Valencia are approximations. Use Kin to review their actual circumstances and ordinary family choices.',
    choices:[
      { id:'household_attention', label:'Give family affairs priority', detail:'Record an intention to attend to the existing family. This moves nobody and arranges no marriage.', operation:'agenda_priority' },
      { id:'household_retain', label:'Keep household arrangements', detail:'Retain the actual family relationships and residences.', operation:'agenda_priority' }
    ] },
  { id:'communities', name:'Residents and obligations', year:1096, season:0,
    text:'The Catholic court governs residents with different faiths and customs. Review current local obligations through ordinary government. A statement of priorities does not issue a charter or guarantee anyone’s safety.',
    choices:[
      { id:'communities_review', label:'Prioritize local administration', detail:'Record an intention to review lawful local obligations. Any actual change keeps its ordinary authority and cost checks.', operation:'agenda_priority' },
      { id:'communities_retain', label:'Retain current arrangements', detail:'Continue without issuing a new communal agreement or altering a place of worship.', operation:'agenda_priority' }
    ] },
  { id:'funds', name:'Paying for government and defense', year:1096, season:1,
    text:'Government and military preparation draw on real resources. Review available funds and ordinary paid forces, or preserve reserves. The optional goals distinguish actual military spending from a declared intention.',
    choices:[
      { id:'funds_prepare', label:'Prioritize paid preparation', detail:'Record a priority only. Use ordinary army controls to review and pay the actual cost of a force.', operation:'agenda_priority' },
      { id:'funds_reserve', label:'Prioritize reserves', detail:'Record a savings intention. The reserve goal still requires {money:120} in the private purse.', operation:'agenda_priority' },
      { id:'funds_retain', label:'Keep present spending priorities', detail:'Make no payment through this review.', operation:'agenda_priority' }
    ] },
  { id:'neighbors', name:'Neighboring courts', year:1096, season:1,
    text:'Earlier royal service and neighboring interests leave room for diplomacy. Review the courts that actually exist and the approaches available through ordinary diplomacy. No pardon, tribute or alliance follows from this review.',
    choices:[
      { id:'neighbors_approach', label:'Prioritize an ordinary diplomatic approach', detail:'Record an intention. Any later approach needs its real counterpart, access, consent and funds.', operation:'agenda_priority' },
      { id:'neighbors_retain', label:'Keep current relations', detail:'Leave existing relations and obligations in place.', operation:'agenda_priority' }
    ] },
  { id:'approaches', name:'The approaches to Valencia', year:1096, season:2,
    text:'Assess current wars, armies and access. Earlier fighting does not mean an army is approaching in this campaign. Actual military operations and supply determine whether the lordship faces a new threat.',
    choices:[
      { id:'approaches_defend', label:'Prioritize ordinary defense', detail:'Record a defensive intention. It creates no host, invasion, battlefield or victory.', operation:'agenda_priority' },
      { id:'approaches_diplomacy', label:'Prioritize a lawful diplomatic response', detail:'Record an intention to use ordinary diplomacy if a suitable current relationship permits it.', operation:'agenda_priority' },
      { id:'approaches_retain', label:'Keep watching under present arrangements', detail:'Retain current policy without asserting that an attack occurred.', operation:'agenda_priority' }
    ] },
  { id:'worship', name:'Household and worship', year:1096, season:3,
    text:'Review the family and institutions that actually remain. A new season does not move residents, establish a cathedral, appoint a bishop or arrange a child’s marriage.',
    choices:[
      { id:'worship_household', label:'Prioritize household and lawful institutional affairs', detail:'Record an intention. Use ordinary family and institutional decisions for any supported action.', operation:'agenda_priority' },
      { id:'worship_defense', label:'Continue to prioritize defense', detail:'Keep defense as a priority without spending or raising forces here.', operation:'agenda_priority' },
      { id:'worship_retain', label:'Retain present arrangements', detail:'Leave family, institutions and current obligations in their actual state.', operation:'agenda_priority' }
    ] },
  { id:'continuing', name:'A continuing lordship', year:1097, season:0,
    text:'Take stock of the jurisdiction and household that actually survive. Future battles, marriages and succession remain open. This personal program can close while ordinary government and any current war continue.',
    choices:[
      { id:'continuing_consolidate', label:'Conclude with consolidation as the priority', detail:'Complete the personal review without acquiring another place or resolving a war.', operation:'agenda_priority' },
      { id:'continuing_finish', label:'Close the opening program', detail:'End these reviews with all actual possessions, people and obligations intact.', operation:'agenda_finish' }
    ] }

changes.after:
intro:'You have held Valencia since June 1094, a Christian lord over a mostly Muslim city, with the Almoravids of Yusuf ibn Tashfin to the south. These priorities shape your court’s story; orders, payments and wars go through Rank & Realm, Land and the map.',
stages:[
  { id:'city', name:'A city already held', year:1096, season:0,
    text:'You took Valencia in June 1094 and beat the Almoravid army that came to retake it at Cuarte that October. Murviedro, inside your county on the map, still holds out against you.',
    choices:[
      { id:'city_administration', label:'Put the city’s government first', detail:'You turn to Valencia’s officials, markets and courts.', operation:'agenda_priority' },
      { id:'city_defense', label:'Ready Valencia against the Almoravids', detail:'You turn to Valencia’s walls and the men who guard them.', operation:'agenda_priority' },
      { id:'city_retain', label:'Leave the city’s business as it stands', detail:'You keep Valencia’s government and purse as they are.', operation:'agenda_priority' }
    ] },
  { id:'household', name:'Jimena and the children', year:1096, season:0,
    text:'Jimena, your son Diego and your daughters Cristina and Maria live with you in Valencia.',
    choices:[
      { id:'household_attention', label:'Give Jimena and the children your time', detail:'You turn to Jimena, Diego, Cristina and Maria.', operation:'agenda_priority' },
      { id:'household_retain', label:'Leave family matters to Jimena', detail:'Jimena runs the household while you see to other business.', operation:'agenda_priority' }
    ] },
  { id:'communities', name:'Residents and obligations', year:1096, season:0,
    text:'Most of Valencia’s people are Muslims who stayed after you took the city in 1094.',
    choices:[
      { id:'communities_review', label:'Settle what Valencia’s Muslims owe you', detail:'You turn to the taxes and rights of the city’s Muslim residents.', operation:'agenda_priority' },
      { id:'communities_retain', label:'Keep the terms of the 1094 surrender', detail:'You leave the Muslims’ judges, mosques and dues as they are.', operation:'agenda_priority' }
    ] },
  { id:'funds', name:'Paying for government and defense', year:1096, season:1,
    text:'Your knights, the walls and the city’s officials are all paid from your private purse.',
    choices:[
      { id:'funds_prepare', label:'Spend on soldiers before savings', detail:'You turn to hiring and paying troops to hold Valencia.', operation:'agenda_priority' },
      { id:'funds_reserve', label:'Build up a reserve in your purse', detail:'You turn to saving; the reserve goal needs {money:120} in your private purse.', operation:'agenda_priority' },
      { id:'funds_retain', label:'Keep spending as it is', detail:'You leave your purse and payments as they stand.', operation:'agenda_priority' }
    ] },
  { id:'neighbors', name:'Neighboring courts', year:1096, season:1,
    text:'You once served Alfonso VI of Leon and Castile, and Peter I of Aragon is a Christian neighbor worth courting.',
    choices:[
      { id:'neighbors_approach', label:'Court Alfonso VI and Peter I', detail:'You turn to sending envoys and gifts to the Christian kings.', operation:'agenda_priority' },
      { id:'neighbors_retain', label:'Leave relations with the kings as they are', detail:'You turn to Valencia and leave the Christian courts alone for now.', operation:'agenda_priority' }
    ] },
  { id:'approaches', name:'The approaches to Valencia', year:1096, season:2,
    text:'The Almoravids hold Denia and Murcia to the south and mean to take Valencia back.',
    choices:[
      { id:'approaches_defend', label:'Guard the roads from the south', detail:'You turn to the walls and the southern approaches.', operation:'agenda_priority' },
      { id:'approaches_diplomacy', label:'Seek allies against the Almoravids', detail:'You turn to Peter I of Aragon and the other Christian courts for help.', operation:'agenda_priority' },
      { id:'approaches_retain', label:'Keep watch and wait', detail:'You hold to your plans and watch the south.', operation:'agenda_priority' }
    ] },
  { id:'worship', name:'Household and worship', year:1096, season:3,
    text:'Valencia’s Christians want a cathedral and a bishop of their own, and your children are of an age to marry.',
    choices:[
      { id:'worship_household', label:'Attend to family and church', detail:'You turn to Jimena and the children and to Valencia’s Christian clergy.', operation:'agenda_priority' },
      { id:'worship_defense', label:'Keep the walls first', detail:'You keep your mind on Valencia’s defense this winter.', operation:'agenda_priority' },
      { id:'worship_retain', label:'Leave family and church as they are', detail:'You turn to other business this winter.', operation:'agenda_priority' }
    ] },
  { id:'continuing', name:'A continuing lordship', year:1097, season:0,
    text:'Spring 1097: you have held Valencia for nearly three years, and the Almoravids still threaten it from the south.',
    choices:[
      { id:'continuing_consolidate', label:'Make Valencia secure for your heirs', detail:'You close the reviews with Valencia’s defense and government as your aim.', operation:'agenda_priority' },
      { id:'continuing_finish', label:'Close the opening program', detail:'The reviews end here, with your lands and family as they stand.', operation:'agenda_finish' }
    ] }
